package com.picalibrary.android;

import android.app.*;
import android.content.Intent;
import android.os.Bundle;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Native Pica discovery/favorites surface. Every result is merged into the unified catalog. */
public final class PicaBrowseActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private EditText search;private TextView status;private ProgressBar loading;private LinearLayout results;private int page=1;private String keyword="",category="",mode="leaderboard";private boolean destroyed;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Ui.BG);getWindow().setNavigationBarColor(Ui.BG);render();if(PicaAccountStore.load(this).signedIn())leaderboard();}
    private Button button(String label,View.OnClickListener action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(Ui.PRIMARY);b.setOnClickListener(action);return b;}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BG);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(button("‹ 返回",v->finish()));bar.addView(Ui.text(this,"Pica 在线",22,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("账号",v->startActivity(new Intent(this,PicaAccountActivity.class))));root.addView(bar);search=new EditText(this);search.setSingleLine(true);search.setHint("搜索 Pica 漫画");search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);search.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEARCH){startSearch();return true;}return false;});root.addView(search);LinearLayout actions=new LinearLayout(this);actions.addView(button("搜索",v->startSearch()),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("收藏",v->favorites()),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("24h 排行",v->leaderboard()),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("分类",v->chooseCategory()),new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);status=Ui.text(this,PicaAccountStore.load(this).configured()?"手机直接访问 Pica，可在线阅读并下载到手机":"请先配置 Pica 账号",12,Ui.MUTED,false);root.addView(status);loading=new ProgressBar(this);loading.setVisibility(View.GONE);root.addView(loading);ScrollView scroll=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);results.setPadding(Ui.dp(this,10),Ui.dp(this,5),Ui.dp(this,10),Ui.dp(this,24));scroll.addView(results);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();}
    @Override protected void onResume(){super.onResume();if(!PicaAccountStore.load(this).configured())status.setText("请先配置 Pica 账号");}
    private boolean requireAccount(){if(PicaAccountStore.load(this).configured())return true;new AlertDialog.Builder(this).setTitle("需要 Pica 账号").setMessage("手机会直接连接 Pica API。登录后即可搜索、收藏、在线阅读与下载。") .setNegativeButton("取消",null).setPositiveButton("去登录",(d,w)->startActivity(new Intent(this,PicaAccountActivity.class))).show();return false;}
    private void startSearch(){if(!requireAccount())return;keyword=search.getText().toString().trim();category="";page=1;mode=keyword.isEmpty()?"leaderboard":"search";reload();}
    private void leaderboard(){if(!requireAccount())return;keyword="";category="";page=1;mode="leaderboard";reload();}
    private void favorites(){if(!requireAccount())return;keyword="";category="";page=1;mode="favorites";reload();}
    private void chooseCategory(){if(!requireAccount())return;busy("正在读取分类…");worker.submit(()->{try{List<String> values=new PicaClient(this).categories();runOnUiThread(()->{if(destroyed)return;loading.setVisibility(View.GONE);new AlertDialog.Builder(this).setTitle("Pica 分类").setItems(values.toArray(new String[0]),(d,index)->{category=values.get(index);keyword="";page=1;mode="category";reload();}).show();});}catch(Exception e){fail(e);}});}
    private void reload(){if(!requireAccount())return;if("search".equals(mode))loadSearch();else if("category".equals(mode))loadCategory();else if("favorites".equals(mode))loadFavorites();else loadLeaderboard();}
    private void loadSearch(){busy("正在搜索 Pica…");worker.submit(()->{try{PicaClient.ComicPage value=new PicaClient(this).search(keyword,page,"ld",Collections.emptyList());merge(value.comics,false);runOnUiThread(()->showComics(value.comics,"搜索结果 · 第 "+value.page+" / "+value.pages+" 页",value.pages));}catch(Exception e){fail(e);}});}
    private void loadCategory(){busy("正在读取分类 · "+category);worker.submit(()->{try{PicaClient.ComicPage value=new PicaClient(this).browse(category,"","dd",page);merge(value.comics,false);runOnUiThread(()->showComics(value.comics,category+" · 第 "+value.page+" / "+value.pages+" 页",value.pages));}catch(Exception e){fail(e);}});}
    private void loadFavorites(){busy("正在读取 Pica 收藏…");worker.submit(()->{try{PicaClient.ComicPage value=new PicaClient(this).favorites(page,"dd");merge(value.comics,true);runOnUiThread(()->showComics(value.comics,"我的收藏 · 第 "+value.page+" / "+value.pages+" 页",value.pages));}catch(Exception e){fail(e);}});}
    private void loadLeaderboard(){busy("正在读取 24h 排行…");worker.submit(()->{try{List<PicaClient.Comic> comics=new PicaClient(this).leaderboard();merge(comics,false);runOnUiThread(()->showComics(comics,"24h 排行 · "+comics.size()+" 本",1));}catch(Exception e){fail(e);}});}
    private void merge(List<PicaClient.Comic> comics,boolean favorite){UnifiedPicaCatalogSync.mergeAll(this,comics);if(favorite){UnifiedCatalogStore.Snapshot snapshot=UnifiedCatalogStore.load(this);for(PicaClient.Comic comic:comics){UnifiedCatalogStore.Entry entry=snapshot.byId.get(comic.id);if(entry!=null)entry.favorite=true;}UnifiedCatalogStore.save(this,snapshot);}}
    private void busy(String text){runOnUiThread(()->{loading.setVisibility(View.VISIBLE);status.setText(text);});}
    private void fail(Exception e){runOnUiThread(()->{if(destroyed)return;loading.setVisibility(View.GONE);status.setText("Pica 读取失败："+(e.getMessage()==null?"未知错误":e.getMessage()));});}
    private void showComics(List<PicaClient.Comic> comics,String label,int pages){if(destroyed)return;loading.setVisibility(View.GONE);status.setText(label);results.removeAllViews();for(PicaClient.Comic comic:comics){UnifiedCatalogStore.Entry entry=UnifiedCatalogStore.load(this).byId.get(comic.id);LinearLayout card=Ui.card(this);LinearLayout row=new LinearLayout(this);ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(cover,new LinearLayout.LayoutParams(Ui.dp(this,82),Ui.dp(this,116)));LinearLayout text=new LinearLayout(this);text.setOrientation(LinearLayout.VERTICAL);text.setPadding(Ui.dp(this,12),0,0,0);text.addView(Ui.text(this,comic.title,17,Ui.TEXT,true));text.addView(Ui.text(this,comic.author,12,Ui.MUTED,false));if(!comic.tags.isEmpty())text.addView(Ui.text(this,String.join(" · ",comic.tags.subList(0,Math.min(4,comic.tags.size()))),11,Ui.PRIMARY,false));text.addView(Ui.text(this,"Pica 在线 · "+comic.epsCount+" 章 · "+comic.pagesCount+" 页",11,Ui.MUTED,false));row.addView(text,new LinearLayout.LayoutParams(0,-2,1));card.addView(row);if(entry!=null)CoverRepository.load(this,cover,entry,0xffebe8ef);card.setOnClickListener(v->open(comic));results.addView(card);}if(pages>1){LinearLayout nav=new LinearLayout(this);nav.addView(button("上一页",v->{if(page>1){page--;reload();}}),new LinearLayout.LayoutParams(0,-2,1));nav.addView(button("下一页",v->{if(page<pages){page++;reload();}}),new LinearLayout.LayoutParams(0,-2,1));results.addView(nav);}}
    private void open(PicaClient.Comic comic){UnifiedPicaCatalogSync.merge(this,comic);Intent i=new Intent(this,UnifiedComicDetailActivity.class);i.putExtra("comicId",comic.id);i.putExtra("title",comic.title);i.putExtra("author",comic.author);startActivity(i);}
    @Override protected void onDestroy(){destroyed=true;worker.shutdownNow();super.onDestroy();}
}
